-- поток: fin; read-only
select account,to_char((payload->>'rr_dt')::date,'YYYY-MM') ym,min((payload->>'rr_dt')::date)::text first_date,max((payload->>'rr_dt')::date)::text last_date,count(distinct (payload->>'rr_dt')::date) days,count(*) rows,sum(case payload->>'doc_type_name' when 'Продажа' then coalesce((payload->>'retail_amount')::numeric,0) when 'Возврат' then -coalesce((payload->>'retail_amount')::numeric,0) else 0 end) net from raw_wb_report where (payload->>'rr_dt')::date between '2024-09-01' and '2024-10-31' or (payload->>'rr_dt')::date between '2025-09-01' and '2025-10-31' group by 1,2 order by 1,2;
